class Solution {
  private static boolean feasible(
      int n, int[][] edges, int source, int target, int k, int threshold) {
    List<int[]>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int[] e : edges) {
      int cost = e[2] > threshold ? 1 : 0;
      adj[e[0]].add(new int[] {e[1], cost});
      adj[e[1]].add(new int[] {e[0], cost});
    }
    int[] dist = new int[n];
    java.util.Arrays.fill(dist, Integer.MAX_VALUE);
    dist[source] = 0;
    java.util.ArrayDeque<Integer> dq = new java.util.ArrayDeque<>();
    dq.add(source);
    while (!dq.isEmpty()) {
      int u = dq.pollFirst();
      for (int[] e : adj[u]) {
        if (dist[u] + e[1] < dist[e[0]]) {
          dist[e[0]] = dist[u] + e[1];
          if (e[1] == 0) dq.addFirst(e[0]);
          else dq.addLast(e[0]);
        }
      }
    }
    return dist[target] <= k;
  }

  public int minimumThreshold(int n, int[][] edges, int source, int target, int k) {
    int[] cand = new int[edges.length + 1];
    for (int i = 0; i < edges.length; i++) cand[i + 1] = edges[i][2];
    java.util.Arrays.sort(cand);
    if (!feasible(n, edges, source, target, k, cand[cand.length - 1])) return -1;
    int lo = 0, hi = cand.length - 1;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (feasible(n, edges, source, target, k, cand[mid])) hi = mid;
      else lo = mid + 1;
    }
    return cand[lo];
  }
}
